namespace elit21::shopify::webhooks {OrderWebhookHandler::OrderWebhookHandler():platform::BusinessComponent("OrderWebhookHandler","Persistent Shopify webhook domain handler",platform::BusinessComponentSpec{"shopify","handle_webhook",{},true,false,16U*1024U*1024U}){}OrderWebhookHandler::OrderWebhookHandler(Database&database):OrderWebhookHandler(){database_=&database;}Result<void>OrderWebhookHandler::handle(const ShopifyWebhook&event){if(!database_)return Result<void>::failure("OrderWebhookHandler is not bound to Database");return persistWebhookTask(*database_,event,{ShopifyWebhookTopic::orders_paid,ShopifyWebhookTopic::orders_cancelled});}platform::OperationResult OrderWebhookHandler::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["database_bound"]=database_?1.0:0.0;r.attributes["handler"]="OrderWebhookHandler";return r;}}
